.body-month-panel .body-graph-summary>span{grid-column:1/-1;min-height:28px;display:flex;align-items:center;padding-right:44px}
.body-month-panel .body-graph-summary>strong{grid-column:2;grid-row:2;text-align:right}
.body-month-panel .body-graph-summary>small{grid-column:1;grid-row:2}
